import{f as d,J as n,o as a,c as r,k as t,a as s,b as l,w as o,K as h,a7 as c,a6 as g}from"./chunks/framework.Dd1qhYRL.js";const v=JSON.parse(`{"title":"Reverse-engineering an existing database","description":"Point an agent at a database you already run, read through noorm's MCP server, and have the ignatius-modeling skill extract an ignatius model from it.","frontmatter":{"title":"Reverse-engineering an existing database","description":"Point an agent at a database you already run, read through noorm's MCP server, and have the ignatius-modeling skill extract an ignatius model from it."},"headers":[],"relativePath":"modeling/reverse-engineering.md","filePath":"modeling/reverse-engineering.md"}`),m={name:"modeling/reverse-engineering.md"};function p(u,e,b,f,k,y){const i=n("Mermaid");return a(),r("div",null,[e[1]||(e[1]=t("h1",{id:"reverse-engineering-an-existing-database",tabindex:"-1"},[s("Reverse-engineering an existing database "),t("a",{class:"header-anchor",href:"#reverse-engineering-an-existing-database","aria-label":"Permalink to “Reverse-engineering an existing database”"},"​")],-1)),e[2]||(e[2]=t("p",null,"Extract an ignatius model from a database you already run, with an agent that reads the schema through noorm's MCP server.",-1)),e[3]||(e[3]=t("p",null,"The agent reads the database through noorm, writes the model files, and checks them. You review the result:",-1)),(a(),l(c,null,{default:o(()=>[h(i,{id:"mermaid-9",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20You%0A%20%20%20%20participant%20Agent%0A%20%20%20%20participant%20MCP%20as%20noorm%20MCP%0A%20%20%20%20participant%20DB%20as%20database%0A%20%20%20%20participant%20Files%20as%20model%20files%0A%20%20%20%20participant%20Validate%20as%20ignatius%20validate%0A%20%20%20%20You-%3E%3EAgent%3A%20%2Fignatius-modeling%20discover%0A%20%20%20%20Agent-%3E%3EMCP%3A%20run_noorm_cmd%20list%2C%20detail%0A%20%20%20%20MCP-%3E%3EDB%3A%20read%20system%20catalogs%0A%20%20%20%20DB--%3E%3EMCP%3A%20tables%2C%20columns%2C%20keys%0A%20%20%20%20MCP--%3E%3EAgent%3A%20JSON%20results%0A%20%20%20%20Agent-%3E%3EFiles%3A%20write%20entity%20and%20flow%20files%0A%20%20%20%20Agent-%3E%3EValidate%3A%20check%20the%20model%20folder%0A%20%20%20%20Validate--%3E%3EAgent%3A%20findings%0A%20%20%20%20Agent-%3E%3EYou%3A%20questions%20the%20schema%20cannot%20answer%0A%20%20%20%20You-%3E%3EFiles%3A%20ignatius%20serve%20-o%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=g(`<p><code>noorm mcp init</code> runs once per project. The slash command runs in the agent:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ignatius-modeling discover</span></span></code></pre></div><h2 id="what-do-i-set-up-first" tabindex="-1">What do I set up first? <a class="header-anchor" href="#what-do-i-set-up-first" aria-label="Permalink to “What do I set up first?”">​</a></h2><ol><li>A model root: any folder with an <code>ignatius.yml</code>. <code>/ignatius-modeling model</code> scaffolds one. <code>mkdir -p models/legacy &amp;&amp; echo &quot;name: Legacy Schema&quot; &gt; models/legacy/ignatius.yml</code> is the minimum. Keep it in the repository whose schema it describes.</li><li>The agent&#39;s MCP config. <code>noorm mcp init</code> writes <code>.mcp.json</code> for Claude Code, and <code>noorm mcp init --agent cursor</code> writes <code>.cursor/mcp.json</code>. The agent gets two tools, <code>noorm_help</code> and <code>run_noorm_cmd</code>.</li><li>A noorm config for the database you mean. The agent connects to the active config unless it names another. A model of staging is not a model of production.</li><li>The skill and the binary, both on <a href="/download.html">Download</a>.</li></ol><h2 id="how-do-i-keep-the-agent-read-only" tabindex="-1">How do I keep the agent read-only? <a class="header-anchor" href="#how-do-i-keep-the-agent-read-only" aria-label="Permalink to “How do I keep the agent read-only?”">​</a></h2><p>A config that never declared <code>access</code> gives agents <code>viewer</code>: schema exploration and read-only SQL. That is all this job needs, so this step is usually a check. Confirm it in <code>noorm ui</code> under Config, then Edit.</p><p>The role covers MCP and an agent that shells out to <code>noorm</code>. See <a href="/guide/automation/mcp.html">MCP</a> for the full role table.</p><div class="warning custom-block"><p class="custom-block-title">Roles prevent accidents, not attacks</p><p>An agent that shells out can set <code>NOORM_CHANNEL=user</code>. Reverse-engineering also feeds the agent table comments, column descriptions, and procedure bodies that you may not have written. Connect noorm with a database user that holds only <code>SELECT</code> and catalog permissions, so the role is the second line of defense.</p></div><h2 id="what-does-the-database-user-need" tabindex="-1">What does the database user need? <a class="header-anchor" href="#what-does-the-database-user-need" aria-label="Permalink to “What does the database user need?”">​</a></h2><p>A permissions gap does not raise an error. The catalogs return fewer rows, so the model looks finished and misses tables. <a href="https://www.postgresql.org/docs/current/infoschema-tables.html" target="_blank" rel="noreferrer">PostgreSQL</a>, <a href="https://dev.mysql.com/doc/refman/8.0/en/information-schema-introduction.html" target="_blank" rel="noreferrer">MySQL</a>, and <a href="https://learn.microsoft.com/en-us/sql/relational-databases/security/metadata-visibility-configuration" target="_blank" rel="noreferrer">SQL Server</a> each show only objects the user owns or holds a privilege on.</p><table tabindex="0"><thead><tr><th>Dialect</th><th>noorm reads</th><th>Grant</th></tr></thead><tbody><tr><td>PostgreSQL</td><td><code>information_schema</code>, <code>pg_catalog</code></td><td><code>GRANT USAGE ON SCHEMA public TO modeler;</code> and <code>GRANT SELECT ON ALL TABLES IN SCHEMA public TO modeler;</code></td></tr><tr><td>MySQL</td><td><code>information_schema</code></td><td><code>GRANT SELECT ON mydb.* TO &#39;modeler&#39;@&#39;%&#39;;</code></td></tr><tr><td>SQL Server</td><td><code>sys</code> catalog views</td><td><code>GRANT VIEW DEFINITION TO modeler;</code></td></tr><tr><td>SQLite</td><td><code>sqlite_master</code>, <code>PRAGMA</code></td><td>none, file access</td></tr></tbody></table><p>Before the agent writes anything, have it run <code>overview</code>, which returns a count for each object type. Compare the table count with what you know is there.</p><h2 id="what-does-the-agent-extract" tabindex="-1">What does the agent extract? <a class="header-anchor" href="#what-does-the-agent-extract" aria-label="Permalink to “What does the agent extract?”">​</a></h2><p>Foreign keys give the agent entities and relationships. Only code gives it processes, so offer the repository too.</p><table tabindex="0"><thead><tr><th>In the database or code</th><th>In the model</th></tr></thead><tbody><tr><td>Table</td><td>Entity, named exactly as the table. <code>sales_orders</code> stays <code>sales_orders</code></td></tr><tr><td>Column</td><td>Attribute, nullability kept. A <code>NOT NULL</code> foreign key is a mandatory parent</td></tr><tr><td>Primary key</td><td><code>key-inherited</code> when it contains a foreign key, <code>orm-oriented</code> for a lone surrogate <code>id</code></td></tr><tr><td>Foreign key</td><td>Relationship. Whether it is identifying comes from where the key sits</td></tr><tr><td>Table whose whole primary key is its parent&#39;s</td><td>Subtype member</td></tr><tr><td><code>SELECT</code> in a handler or procedure</td><td>Input flow with that column list</td></tr><tr><td><code>INSERT</code> in a handler or procedure</td><td>Output flow with those columns</td></tr><tr><td>A few real rows per table</td><td><code>examples:</code>, with PII and secrets masked</td></tr></tbody></table><p>The skill records anti-patterns instead of fixing them. A junk-drawer table or a surrogate key where the real identity is composite is captured as it is, then raised with you as a question.</p><h2 id="how-far-does-extraction-get" tabindex="-1">How far does extraction get? <a class="header-anchor" href="#how-far-does-extraction-get" aria-label="Permalink to “How far does extraction get?”">​</a></h2><p>IDEF1X names the approach bottom-up and sorts its results into levels:</p><table tabindex="0"><thead><tr><th>Level</th><th>You get</th><th>Worth</th></tr></thead><tbody><tr><td>1</td><td>Current-system documentation</td><td>Shows what <strong>is</strong></td></tr><tr><td>2</td><td>Application-level logical model</td><td>The requirements the system satisfies today, right or wrong</td></tr><tr><td>3</td><td>Business-level model</td><td>A basis for future design. Needs the business in the room</td></tr></tbody></table><p>We read a schema as enough for level 1 and part of level 2. Level 3 lives with the people who run the business. A model of what you have is not a model of what you want. The <a href="https://www.skills.sh/damusix/skills/idef1x" target="_blank" rel="noreferrer"><code>idef1x</code> skill</a> carries the method.</p><h2 id="how-do-i-review-the-result" tabindex="-1">How do I review the result? <a class="header-anchor" href="#how-do-i-review-the-result" aria-label="Permalink to “How do I review the result?”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> models/legacy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> models/legacy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span></span></code></pre></div><p><code>validate</code> exits <code>1</code> on errors and <code>0</code> otherwise, so it also gates a pull request. A clean run means the model is consistent. Two failures pass it: a table the agent could not see, and a purpose the agent had to guess. An entity body that restates its columns is the second one.</p><p>The skill ends the session with a change note. <code>serve</code> shows the edit beside it, and <code>ignatius approve</code> accepts it; see <a href="/modeling/modeling-skill.html">the modeling skill</a>. Walk the people who run the business through the served model.</p><h2 id="what-bites" tabindex="-1">What bites <a class="header-anchor" href="#what-bites" aria-label="Permalink to “What bites”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>The model is clean and tables are missing</td><td>The database user cannot see them</td><td>Grant catalog access, then compare <code>overview</code> counts</td></tr><tr><td>The agent cannot find your config</td><td><code>access.agent</code> is <code>false</code>, which hides the config from agents</td><td>Set <code>agent</code> to <code>viewer</code></td></tr><tr><td>Links and <code>db:</code> tokens break</td><td>An entity id no longer matches its table name</td><td>Restore the source name. Raise a rename as a question</td></tr><tr><td>Real customer values in a committed file</td><td><code>examples:</code> come from live rows</td><td>Mask them before you commit</td></tr><tr><td>An entity body restates its columns</td><td>The schema cannot say what the entity is for</td><td>Write the purpose yourself</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/modeling/modeling-skill.html">The modeling skill</a>: the modes and the change-review loop</li><li><a href="/modeling/entities.html">Entities and key inheritance</a>: the files the agent writes</li><li><a href="/modeling/data-flows.html">Data flows</a>: processes, externals, and stores</li><li><a href="/guide/automation/mcp.html">MCP</a>: the server and its access roles</li></ul>`,29))])}const A=d(m,[["render",p]]);export{v as __pageData,A as default};
